$builder = json_decode($item['builder_json'] ?? '', true);
if (!is_array($builder) || !$builder) {
    $legacy = (string)($item['content'] ?? '');
    $legacySections = [];
    if ($legacy !== '') {
        preg_match_all('/<section\b[^>]*>(.*?)<\/section>/is', $legacy, $matches);
        foreach ($matches[1] ?? [] as $i => $inner) {
            $legacySections[] = ['id'=>'legacy_'.($i+1).'_'.uniqid(),'type'=>'html','data'=>['theme'=>($i===1?'dark':'light'),'content'=>$inner],'hidden'=>false];
        }
    }
    $builder = $legacySections ?: [
        ['id'=>'hero_'.uniqid(),'type'=>'hero','data'=>['eyebrow'=>$item['category'] ?? 'Legal Update','title'=>$item['title'],'text'=>$item['excerpt'],'image'=>'','button_text'=>'Request Appointment ↗','button_url'=>'appointment','theme'=>'light']],
        ['id'=>'intro_'.uniqid(),'type'=>'richtext','data'=>['eyebrow'=>'Legal Update','title'=>'Read the update.','content'=>$item['content'] ?: '<p>Write the update content here.</p>','theme'=>'light']],
        ['id'=>'quote_'.uniqid(),'type'=>'quote','data'=>['label'=>'LEX FACTUM','quote'=>'Clear legal information starts with clear facts.','text'=>'<p>Add supporting context or a concise takeaway.</p>','theme'=>'dark']],
    ];
}
