<style>
.builder-head{align-items:center}.builder-head .cms-actions{display:flex;gap:8px;align-items:center}.builder-save,.palette-btn,.template-btn{font:inherit;cursor:pointer}.builder-save{padding:12px 16px;border:1px solid rgba(218,190,142,.28);border-radius:12px;background:#d2ad6d;color:#111;font-size:11px;letter-spacing:.08em}.builder-layout{display:grid;grid-template-columns:310px minmax(0,1fr);gap:16px}.builder-sidebar{margin-top:0;position:sticky;top:15px;align-self:start;max-height:calc(100vh - 30px);overflow:auto}.builder-side-title{color:#d5b477;font-size:10px;letter-spacing:.16em;margin-bottom:14px}.add-title{margin-top:24px}.builder-row{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:end}.section-palette{display:grid;grid-template-columns:1fr 1fr;gap:7px}.palette-btn,.template-btn{border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.035);color:#cfd2d1;border-radius:10px;padding:10px;text-align:left;font-size:11px}.palette-btn span,.template-btn span{color:#d5b477;margin-right:7px}.palette-btn:hover,.template-btn:hover{border-color:rgba(218,190,142,.35);background:rgba(218,190,142,.07)}.template-list{display:grid;gap:7px}.template-btn{width:100%}.builder-help{margin-top:18px;padding:12px;border:1px dashed rgba(218,190,142,.2);border-radius:10px;color:#7f8789;font-size:11px;line-height:1.6}.builder-canvas{min-width:0}.section-list{min-height:400px;display:grid;gap:12px}.builder-section{border:1px solid rgba(255,255,255,.09);background:rgba(255,255,255,.035);border-radius:18px;overflow:hidden}.builder-section.is-hidden{opacity:.48}.builder-section-head{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid rgba(255,255,255,.07);background:rgba(0,0,0,.16)}.drag-handle{cursor:grab;color:#d5b477;font-size:18px;line-height:1}.section-name{flex:1;color:#d9dcda;font-size:11px;letter-spacing:.1em}.section-actions{display:flex;gap:6px}.section-actions button{border:1px solid rgba(255,255,255,.09);background:transparent;color:#aeb4b4;border-radius:8px;padding:6px 8px;cursor:pointer;font-size:11px}.section-actions button:hover{color:#e0bd7c;border-color:rgba(218,190,142,.3)}.builder-section-body{padding:16px}.builder-section-body .field:last-child{margin-bottom:0}.builder-section-body input,.builder-section-body textarea,.builder-section-body select{background:#0e1113}.item-list{display:grid;gap:10px}.item-row{border:1px solid rgba(255,255,255,.07);padding:12px;border-radius:12px;background:rgba(0,0,0,.12)}.item-row-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px;color:#92999b;font-size:10px}.item-row button{background:transparent;border:0;color:#aeb4b4;cursor:pointer}.item-row button:hover{color:#df8f8f}.add-item{margin-top:8px;padding:9px 12px;border:1px solid rgba(218,190,142,.22);border-radius:9px;background:rgba(218,190,142,.06);color:#d5b477;cursor:pointer;font-size:10px}.drop-hint{margin-top:12px;padding:25px;text-align:center;border:1px dashed rgba(218,190,142,.18);border-radius:14px;color:#686f71;font-size:10px;letter-spacing:.16em}.ck-editor__editable{min-height:150px}.ck.ck-editor{color:#111}.ck.ck-toolbar{border-radius:8px 8px 0 0}.ck-editor__editable{border-radius:0 0 8px 8px}.flash-ok,.flash-error{padding:12px;border-radius:10px;margin-bottom:12px;font-size:12px}.flash-ok{background:rgba(110,170,120,.1);color:#b7d5bc}.flash-error{background:rgba(190,100,100,.1);color:#e1b1b1}@media(max-width:980px){.builder-layout{grid-template-columns:1fr}.builder-sidebar{position:relative;top:auto;max-height:none}.section-palette{grid-template-columns:repeat(2,1fr)}}
</style>
<script>
const initialSections = <?= json_encode($builder, JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE) ?>;
const csrfName = '<?= csrf_token() ?>';
const csrfHash = '<?= csrf_hash() ?>';
let sections = initialSections.map(s => ({id:s.id || uid(), type:s.type, data:s.data||{}, hidden:!!s.hidden}));
const editors = new Map();
const sectionsEl = document.getElementById('sections');
const typeNames = {hero:'Hero',richtext:'Rich Text / CKEditor',html:'Free HTML / Legacy',cards:'Card Grid',process:'Process / 3 Columns',quote:'Quote / Callout',image_text:'Image + Text',cta:'Call To Action'};
function uid(){return 'sec_'+Math.random().toString(36).slice(2)+Date.now().toString(36)}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label>${esc(label)}</label>${type==='textarea'?`<textarea data-key="${esc(name)}" ${extra}>${esc(value)}</textarea>`:type==='select'?`<select data-key="${esc(name)}">${extra}</select>`:`<input data-key="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}>`}</div>`}
function richField(label,key,value){return `<div class="field rich-field"><label>${esc(label)}</label><textarea data-key="${esc(key)}" class="rich-editor">${esc(value||'')}</textarea></div>`}
function itemRows(data,key,fields){let arr=Array.isArray(data[key])?data[key]:[];return `<div class="item-list" data-items="${key}">${arr.map((it,i)=>`<div class="item-row" data-item-index="${i}"><div class="item-row-head"><span>ITEM ${String(i+1).padStart(2,'0')}</span><button type="button" data-remove-item>Remove</button></div>${fields.map(f=>f.type==='rich'?richField(f.label,f.key,it[f.key]||''):field(f.label,f.key,it[f.key]||'',f.type||'text')).join('')}</div>`).join('')}</div><button type="button" class="add-item" data-add-item="${key}">+ ADD ITEM</button>`}
function sectionBody(s){const d=s.data||{};switch(s.type){case'hero':return field('EYEBROW','eyebrow',d.eyebrow)+field('TITLE','title',d.title)+field('TEXT','text',d.text,'textarea')+field('IMAGE','image',d.image)+field('BUTTON TEXT','button_text',d.button_text)+field('BUTTON URL','button_url',d.button_url||'appointment')+field('THEME','theme',d.theme||'light','select','<option value="light">Light</option><option value="dark">Dark</option>');case'richtext':return field('EYEBROW','eyebrow',d.eyebrow)+field('TITLE','title',d.title)+richField('CONTENT','content',d.content)+field('THEME','theme',d.theme||'light','select','<option value="light">Light</option><option value="dark">Dark</option>');case'html':return richField('CONTENT','content',d.content||'')+field('THEME','theme',d.theme||'light','select','<option value="light">Light</option><option value="dark">Dark</option>');case'cards':return field('EYEBROW','eyebrow',d.eyebrow)+field('TITLE','title',d.title)+itemRows(d,'items',[{label:'NUMBER / LABEL',key:'label'},{label:'TITLE',key:'title'},{label:'TEXT',key:'text',type:'rich'}])+field('THEME','theme',d.theme||'light','select','<option value="light">Light</option><option value="dark">Dark</option>');case'process':return field('EYEBROW','eyebrow',d.eyebrow)+field('TITLE','title',d.title)+itemRows(d,'items',[{label:'LABEL',key:'label'},{label:'TITLE',key:'title'},{label:'TEXT',key:'text',type:'rich'}])+field('THEME','theme',d.theme||'dark','select','<option value="dark">Dark</option><option value="light">Light</option>');case'quote':return field('LABEL','label',d.label)+field('QUOTE','quote',d.quote,'textarea')+richField('TEXT','text',d.text)+field('THEME','theme',d.theme||'light','select','<option value="light">Light</option><option value="dark">Dark</option>');case'image_text':return field('EYEBROW','eyebrow',d.eyebrow)+field('TITLE','title',d.title)+richField('CONTENT','content',d.content)+field('IMAGE','image',d.image)+field('SIDE','side',d.side||'right','select','<option value="right">Image right</option><option value="left">Image left</option>')+field('THEME','theme',d.theme||'dark','select','<option value="dark">Dark</option><option value="light">Light</option>');case'cta':return field('EYEBROW','eyebrow',d.eyebrow)+field('TITLE','title',d.title)+richField('CONTENT','content',d.content)+field('BUTTON TEXT','button_text',d.button_text)+field('BUTTON URL','button_url',d.button_url||'appointment')+field('THEME','theme',d.theme||'dark','select','<option value="dark">Dark</option><option value="light">Light</option>');default:return richField('CONTENT','content',d.content||'');}}
function render(){sectionsEl.innerHTML='';editors.forEach(e=>{try{e.destroy()}catch(_){}});editors.clear();sections.forEach((s,i)=>{const wrap=document.createElement('section');wrap.className='builder-section'+(s.hidden?' is-hidden':'');wrap.dataset.id=s.id;wrap.innerHTML=`<div class="builder-section-head"><span class="drag-handle">☷</span><span class="section-name">${String(i+1).padStart(2,'0')} · ${esc(typeNames[s.type]||s.type)}</span><div class="section-actions"><button type="button" data-toggle>${s.hidden?'SHOW':'HIDE'}</button><button type="button" data-duplicate>Duplicate</button><button type="button" data-save-template>Save template</button><button type="button" data-delete>Delete</button></div></div><div class="builder-section-body">${sectionBody(s)}</div>`;sectionsEl.appendChild(wrap);wireSection(wrap,s);});}
function wireSection(wrap,s){wrap.querySelectorAll('[data-key]').forEach(el=>{el.addEventListener('input',()=>{if(el.classList.contains('rich-editor'))return;s.data[el.dataset.key]=el.value;});el.addEventListener('change',()=>{s.data[el.dataset.key]=el.value;});});wrap.querySelector('[data-toggle]').onclick=()=>{s.hidden=!s.hidden;render()};wrap.querySelector('[data-delete]').onclick=()=>{if(confirm('Delete this section?')){sections=sections.filter(x=>x.id!==s.id);render()}};wrap.querySelector('[data-duplicate]').onclick=()=>{sections.splice(sections.findIndex(x=>x.id===s.id)+1,0,{id:uid(),type:s.type,data:JSON.parse(JSON.stringify(s.data)),hidden:s.hidden});render()};wrap.querySelector('[data-save-template]').onclick=async()=>{syncSection(wrap,s);const name=prompt('Template name:',typeNames[s.type]||s.type);if(!name)return;const fd=new FormData();fd.append('name',name);fd.append('section_type',s.type);fd.append('data',JSON.stringify(s.data));fd.append(csrfName,csrfHash);const r=await fetch('<?= site_url('admin/cms/templates/store') ?>',{method:'POST',body:fd});const j=await r.json();alert(j.ok?'Template saved. Reload the page to see it.':(j.message||'Could not save template.'))};wrap.querySelector('[data-add-item]')?.addEventListener('click',()=>{const key=wrap.querySelector('[data-add-item]').dataset.addItem;s.data[key]=Array.isArray(s.data[key])?s.data[key]:[];s.data[key].push({label:'',title:'',text:''});render()});wrap.querySelectorAll('[data-remove-item]').forEach(btn=>btn.onclick=()=>{const row=btn.closest('.item-row');const key=wrap.querySelector('[data-items]').dataset.items;syncSection(wrap,s);s.data[key].splice(Number(row.dataset.itemIndex),1);render()});wrap.querySelectorAll('.rich-editor').forEach(el=>{ClassicEditor.create(el,{toolbar:['heading','bold','italic','link','bulletedList','numberedList','blockQuote','insertTable','undo','redo']}).then(ed=>{editors.set(el,ed);ed.model.document.on('change:data',()=>{s.data[el.dataset.key]=ed.getData()})}).catch(console.error)});}
function syncSection(wrap,s){wrap.querySelectorAll('[data-key]').forEach(el=>{if(el.classList.contains('rich-editor'))return;s.data[el.dataset.key]=el.value});wrap.querySelectorAll('[data-items]').forEach(list=>{const key=list.dataset.items;s.data[key]=Array.from(list.querySelectorAll('.item-row')).map(row=>{const obj={};row.querySelectorAll('[data-key]').forEach(el=>obj[el.dataset.key]=el.classList.contains('rich-editor')?(editors.get(el)?.getData()||el.value):el.value);return obj})});}
function syncAll(){document.querySelectorAll('.builder-section').forEach(w=>{const s=sections.find(x=>x.id===w.dataset.id);if(s)syncSection(w,s)});document.getElementById('builder_json').value=JSON.stringify(sections);}
new Sortable(sectionsEl,{animation:160,handle:'.drag-handle',onEnd:e=>{const moved=sections.splice(e.oldIndex,1)[0];sections.splice(e.newIndex,0,moved);render()}});
document.querySelectorAll('[data-add]').forEach(btn=>btn.onclick=()=>{sections.push(defaultSection(btn.dataset.add));render();setTimeout(()=>document.querySelector('.builder-section:last-child')?.scrollIntoView({behavior:'smooth',block:'center'}),50)});
document.querySelectorAll('[data-template]').forEach(btn=>btn.onclick=()=>{let d={};try{d=JSON.parse(btn.dataset.template)}catch(_){}sections.push({id:uid(),type:btn.dataset.templateType,data:d,hidden:false});render()});
document.querySelector('.builder-save').onclick=()=>{syncAll();document.getElementById('practiceBuilderForm').submit()};
function defaultSection(type){const common={id:uid(),type,hidden:false,data:{}};switch(type){case'hero':common.data={eyebrow:'Practice Area',title:'New section',text:'Add a concise introduction.',image:'',button_text:'Request Appointment ↗',button_url:'appointment',theme:'light'};break;case'html':common.data={content:'<p>Write your section here.</p>',theme:'light'};break;case'richtext':common.data={eyebrow:'Overview',title:'A clear heading.',content:'<p>Write your content here.</p>',theme:'light'};break;case'cards':case'process':common.data={eyebrow:'How a matter is approached',title:'A practical, structured view.',items:[{label:'01 / Context',title:'First point',text:'<p>Add content.</p>'},{label:'02 / Context',title:'Second point',text:'<p>Add content.</p>'},{label:'03 / Context',title:'Third point',text:'<p>Add content.</p>'}],theme:type==='process'?'dark':'light'};break;case'quote':common.data={label:'LEX FACTUM',quote:'A considered next step begins with clear facts.',text:'<p>Add supporting context.</p>',theme:'light'};break;case'image_text':common.data={eyebrow:'Related considerations',title:'Image and supporting text.',content:'<p>Add content.</p>',image:'',side:'right',theme:'dark'};break;case'cta':common.data={eyebrow:'NEXT STEP',title:'Request an appointment.',content:'<p>Add supporting text.</p>',button_text:'Request Appointment ↗',button_url:'appointment',theme:'dark'};break;}return common}
render();
</script>
<?= $this->endSection() ?>
